WITH inner_cte1 AS ( SELECT l.SUBJECT_TITLE, l.NUM_ENROLLED_STUDENTS, t.RESPONSIBLE_FACULTY_NAME, t.OFFER_DEPT_NAME, MIN(l.NUM_ENROLLED_STUDENTS) OVER ( ORDER BY t.RESPONSIBLE_FACULTY_MIT_ID ROWS BETWEEN 3 PRECEDING AND 1 FOLLOWING ) AS window_column, l.TERM_CODE FROM LIBRARY_SUBJECT_OFFERED l JOIN TIP_SUBJECT_OFFERED t ON l.TERM_CODE = t.TERM_CODE WHERE l.TERM_CODE = '2014FA' AND t.OFFER_DEPT_NAME = 'Chemistry' ), Total_Chemistry AS ( SELECT COUNT(*) AS Total_Chemistry_Subjects, TERM_CODE FROM TIP_SUBJECT_OFFERED WHERE TERM_CODE = '2014FA' AND OFFER_DEPT_NAME = 'Chemistry' GROUP BY TERM_CODE ), inner_cte2 AS ( SELECT ata.ACADEMIC_YEAR, ata.ACADEMIC_YEAR_DESC, VARIANCE(isd.MAX_ENROLLMENT) AS max_enrollment_variance, STDDEV(isd.MAX_ENROLLMENT) AS max_enrollment_stddev, ccso.DEPARTMENT_NAME FROM IAP_SUBJECT_DETAIL isd JOIN ACADEMIC_TERMS_ALL ata ON isd.TERM_CODE = ata.TERM_CODE JOIN COURSE_CATALOG_SUBJECT_OFFERED ccso ON ata.TERM_CODE = ccso.TERM_CODE WHERE isd.ENROLLMENT_TYPE = 'Advance sign-up required' AND isd.IS_CANCELLED = 'N' AND isd.MAX_ENROLLMENT IS NOT NULL AND ccso.DEPARTMENT_NAME = 'Mathematics' GROUP BY ata.ACADEMIC_YEAR, ata.ACADEMIC_YEAR_DESC, ccso.DEPARTMENT_NAME ), RollupResults AS ( SELECT DEPARTMENT_NAME, ACADEMIC_YEAR_DESC, SUM(max_enrollment_variance) AS total_variance, SUM(max_enrollment_stddev) AS total_stddev FROM inner_cte2 GROUP BY DEPARTMENT_NAME, ACADEMIC_YEAR_DESC WITH ROLLUP HAVING SUM(max_enrollment_variance) IS NOT NULL ) SELECT ic1.SUBJECT_TITLE, ic1.NUM_ENROLLED_STUDENTS, ic1.RESPONSIBLE_FACULTY_NAME, ic1.OFFER_DEPT_NAME, ic1.window_column, tc.Total_Chemistry_Subjects, rr.DEPARTMENT_NAME, rr.ACADEMIC_YEAR_DESC, rr.total_variance, rr.total_stddev FROM inner_cte1 ic1 JOIN Total_Chemistry tc ON ic1.TERM_CODE = tc.TERM_CODE JOIN ACADEMIC_TERMS_ALL ata ON ic1.TERM_CODE = ata.TERM_CODE JOIN RollupResults rr ON rr.DEPARTMENT_NAME = 'Mathematics' ORDER BY ic1.SUBJECT_TITLE, rr.ACADEMIC_YEAR_DESC ;